#pragma once

/** @brief ZzLog 主版本号。 */
#define ZZLOG_VERSION_MAJOR 0
/** @brief ZzLog 次版本号。 */
#define ZZLOG_VERSION_MINOR 1
/** @brief ZzLog 修订版本号。 */
#define ZZLOG_VERSION_PATCH 0

/** @brief 便于整数比较的 ZzLog 版本号。 */
#define ZZLOG_VERSION_NUMBER (ZZLOG_VERSION_MAJOR * 10000 + ZZLOG_VERSION_MINOR * 100 + ZZLOG_VERSION_PATCH)
